/**
 * Worker entry for the Cloudflare-hosted frontend (ADR-0021).
 *
 * Wraps the OpenNext handler (`.open-next/worker.js`, generated by
 * `pnpm cf:build`) with what a managed Next.js host would otherwise provide:
 *
 *   1. `/api/backend/*` goes to the FastAPI service:
 *      the `BACKEND` service binding when bound (ADR-0022), else BACKEND_ORIGIN.
 *   2. `/_next/image` results are cached. The OpenNext handler transforms on every request and sends no Cache-Control.
 *      Only the app's own static files can be optimized (next.config.ts
 *      `localPatterns`), never revocable media, so caching them is safe.
 *   3. `Strict-Transport-Security` (`max-age=63072000`) on every HTTPS response
 *      (the app sets no HSTS of its own).
 *
 * Everything else is the unchanged Next.js app. This file is excluded from the
 * app's tsconfig because it imports build output; wrangler bundles it.
 */
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import openNext from "../.open-next/worker.js";
import { isBackendPath, proxyToBackend } from "../src/lib/cloudflare/backend-proxy";
import { withPlatformForwardedHeaders } from "../src/lib/cloudflare/forwarded-headers";

type Env = {
  BACKEND?: { fetch(request: Request): Promise<Response> };
  BACKEND_ORIGIN?: string;
  NEXT_PUBLIC_APP_ENV?: string;
  CF_VERSION_METADATA?: { id: string };
} & Record<string, unknown>;

const HSTS = "max-age=63072000";
// Browsers re-check after an hour (a deploy may change a public file under the
// same name); the edge copy is keyed by the deployed version, so it can live a day.
const IMAGE_BROWSER_CACHE = "public, max-age=3600, stale-while-revalidate=86400";
const IMAGE_EDGE_CACHE = "public, max-age=86400";

function withHsts(response: Response, request: Request): Response {
  if (new URL(request.url).protocol !== "https:" || response.headers.has("strict-transport-security")) return response;
  // Responses from fetch() have immutable headers; copy only when we must.
  const copy = new Response(response.body, response);
  copy.headers.set("strict-transport-security", HSTS);
  return copy;
}

/** The format the optimizer will pick for this Accept header (it negotiates on it). */
function imageFormat(accept: string | null): string {
  if (accept?.includes("image/avif")) return "avif";
  if (accept?.includes("image/webp")) return "webp";
  return "original";
}

async function optimizedImage(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
  const key = new URL(request.url);
  key.searchParams.set("__format", imageFormat(request.headers.get("accept")));
  key.searchParams.set("__version", env.CF_VERSION_METADATA?.id ?? "dev");
  const cacheKey = new Request(key.toString(), { method: "GET" });
  const cache = caches.default;
  const hit = await cache.match(cacheKey);
  if (hit) return hit;

  const response: Response = await openNext.fetch(request, env, ctx);
  if (response.status !== 200) return response;
  const browser = new Response(response.body, response);
  browser.headers.set("cache-control", IMAGE_BROWSER_CACHE);
  browser.headers.append("vary", "accept");
  const edge = browser.clone();
  edge.headers.set("cache-control", IMAGE_EDGE_CACHE);
  // The Cache API is a no-op on workers.dev; it applies on the custom domain.
  ctx.waitUntil(cache.put(cacheKey, edge).catch(() => undefined));
  return browser;
}

export default {
  async fetch(incoming: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    // Client IP and host headers rebuilt from what Cloudflare guarantees (security audit 2026-10-22).
    const request = withPlatformForwardedHeaders(incoming);
    const { pathname } = new URL(request.url);
    let response: Response;
    if (isBackendPath(pathname)) {
      response = await proxyToBackend(request, { binding: env.BACKEND, origin: env.BACKEND_ORIGIN, appEnv: env.NEXT_PUBLIC_APP_ENV });
    } else if (pathname === "/_next/image" && request.method === "GET") {
      response = await optimizedImage(request, env, ctx);
    } else {
      response = await openNext.fetch(request, env, ctx);
    }
    return withHsts(response, request);
  },
};

// Durable Object classes OpenNext may reference from wrangler.jsonc (none bound today).
// @ts-expect-error: generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "../.open-next/worker.js";
